    box(0.024, 0.028, 0.02, 0, 0.004, 0.344, BLK, 'm', 0.0015)  # bloco de gases à frente do guarda-mão
    fh = cyl(0.0112, 0.392, 0.442, BLK, 'm', seg=20)
