    ap = box(0.017, 0.022, 0.005, 0, 0.0715, -0.085, BLK, 'm', 0.0008); cut(ap, cyl(0.0026, -0.09, -0.08, BLK, 'm', y=0.0735, seg=16, cutter=True))  # abertura (mira de anel)
