    box(0.0028, 0.014, 0.003, 0, 0.073, 0.309, BLK, 'm', 0.0003)
    # carregador curvo de 30 (STANAG) com nervuras
    mg = prof([(0.042, -0.055), (0.104, -0.055), (0.104, -0.075), (0.108, -0.120), (0.118, -0.170), (0.128, -0.205), (0.130, -0.214), (0.066, -0.222), (0.062, -0.212), (0.054, -0.170), (0.046, -0.120), (0.042, -0.075)], 0.022, 0x2a2c2e, 'm', bev=0.0018)
    for sx in (-1, 1):
        for i in range(4): cut(mg, box(0.004, 0.0035, 0.044, sx * 0.011, -0.10 - i * 0.03, 0.075 + i * 0.0062, 0x2a2c2e, 'm', 0, cutter=True, rx=-0.17))
    prof([(0.063, -0.214), (0.132, -0.207), (0.134, -0.218), (0.064, -0.226)], 0.026, BLK, 'v', bev=0.0015)  # base
