def ak():  # AKM / AK-47: perfis medidos na foto de referência (coluna a coluna), tamanho real 0,88 m
    M, M2 = 0x33363b, 0x2a2c30; W, W2 = 0x93532f, 0x9a5a34; MG = 0x585b60
    K = 0.00104; px = lambda x, y: ((x - 300) * K, (83 - y) * K)
    P = lambda L: [px(*q) for q in L]; Z = lambda x: (x - 300) * K; Y = lambda y: (83 - y) * K
    # receptor (chapa), tampa arredondada com degrau atrás, rebites
