    box(0.0025, Y(86) - Y(99), Z(500) - Z(425), 0.0157, (Y(86) + Y(99)) / 2, (Z(425) + Z(500)) / 2, 0x0c0d0e, 'v', 0)  # janela do porta-ferrolho
    # bloco da mira de trás e alça
