    prof(P([(486, 66), (534, 66), (532, 48), (526, 42), (494, 42), (488, 50)]), 0.024, M, 'm', bev=0.001)
    prof(P([(492, 42), (528, 38), (530, 43), (494, 46)]), 0.019, 0x141517, 'm', bev=0.0005)
    box(0.022, 0.0055, 0.009, 0, Y(40), Z(508), M2, 'm', 0.0006); box(0.0025, 0.004, 0.004, 0, Y(36.5), Z(528), 0x0a0a0b, 'v', 0)
    # seletor comprido e manípulo de armar
