    cylx(0.0055, 0.0155, 0.019, Y(80), Z(310), M2, 'm', 12)
    cyl(0.0042, Z(486), Z(512), M2, 'm', y=Y(80), x=0.0215, seg=10); sph(0.0055, 0.0225, Y(80), Z(514), M2)
    # guarda-mãos de madeira (de baixo com sulcos, de cima sobre o tubo de gases), anel da frente
