    for sx in (-1, 1):
        for d in (0, 11): cut(lw, prof(P([(560, 82 + d), (640, 82 + d), (640, 86 + d), (560, 86 + d)]), 0.004, W, 'v', x=sx * 0.024, cutter=True))
    profx(arc(0, Y(57), 0.0168, 0, math.pi, 12) + [(-0.0168, Y(71)), (0.0168, Y(71))], Z(660) - Z(540), W2, 'v', z=Z(540), bev=0.002)  # guarda-mão de cima
    cyl(0.0245, Z(662), Z(670), M, 'm', y=Y(78), seg=22)
    cyl(0.0099, Z(664), Z(742), M2, 'm', y=Y(59.5), seg=14)
    for t in range(3): cylx(0.0016, -0.0105, 0.0105, Y(59.5), Z(676 + t * 9), 0x0a0a0b, 'v', 8)
    prof(P([(735, 50), (746, 50), (746, 63), (766, 74), (766, 99), (735, 100)]), 0.026, M, 'm', bev=0.0012)  # bloco de gases a 45°
    cyl(0.0073, Z(520), Z(868), 0x18191b, 'm', seg=18)  # cano
    cyl(0.0021, Z(668), Z(840), M2, 'm', y=Y(97), seg=8)  # vareta
