    cyl(0.0058, Z(1062), Z(1064), D, 'v', y=Yy(1003), seg=16)  # boca do cano
    cyl(0.0042, Z(1062), Z(1064), D, 'v', y=Yy(1060), seg=12)  # guia da mola
