    prof(P([(1006, 960), (1034, 960), (1032, 948), (1026, 934), (1014, 934), (1008, 948)]), 0.0045, D, 'm', bev=0.0004); box(0.002, 0.002, 0.002, 0, Yy(938), Z(1020) - 0.0012, 0xd8d0b0, 'v', 0)  # mira da frente com ponto
