    prof_r = [(-0.09, 0.0), (-0.09, 0.022), (-0.08, 0.026), (-0.075, 0.016), (0.08, 0.0145), (0.25, 0.018), (0.42, 0.028), (0.62, 0.033), (0.70, 0.032), (0.72, 0.024), (0.725, 0.0)]
